using BattleHorizons.Player;
using UnityEngine;

namespace BattleHorizons.UI
{
    /// <summary>
    /// Attaches the on-screen controls to a scene at runtime.
    ///
    /// The control rig is generated by <see cref="MobileControlsBuilder"/> rather
    /// than saved into the scene, so this component is the one thing a scene needs
    /// to have touch input. Keeping it separate also means the rig can be rebuilt
    /// at a different resolution or skipped entirely (desktop play) without editing
    /// a saved canvas.
    ///
    /// <see cref="buildInEditor"/> is on by default: the editor is where the touch
    /// layout gets checked, and the bottom-left stick doubles as a movement source
    /// for a mouse-only machine.
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class TouchControlsHost : MonoBehaviour
    {
        [SerializeField] private ThirdPersonMotor motor;
        [SerializeField] private PlayerInputRouter router;
        [SerializeField] private bool buildInEditor = true;
        [SerializeField] private bool hideWhenInactive;

        private MobileControlsBuilder.Rig _rig;
        private bool _built;

        public MobileControlsBuilder.Rig Rig => _rig;

        public void Configure(ThirdPersonMotor targetMotor, PlayerInputRouter targetRouter)
        {
            motor = targetMotor;
            router = targetRouter;
        }

        private void Start()
        {
            if (motor == null)
            {
                motor = FindFirstObjectByType<ThirdPersonMotor>();
            }

            if (router == null)
            {
                router = FindFirstObjectByType<PlayerInputRouter>();
            }

            if (motor == null || (!Application.isMobilePlatform && !(buildInEditor && Application.isEditor)))
            {
                if (hideWhenInactive)
                {
                    gameObject.SetActive(false);
                }

                return;
            }

            _rig = MobileControlsBuilder.Build(transform, router, motor);
            _built = true;
        }

        private void OnDestroy()
        {
            if (_built && _rig.Root != null)
            {
                Destroy(_rig.Root);
            }
        }
    }
}
